"""Sphinx configuration of the MR_AHA documentation.

The site has three kinds of pages:

* guides, written in Markdown (MyST) under ``source/``;
* the Python reference, generated by sphinx-autoapi from the docstrings of
  ``third_party/MR_AHA/python/mr_aha``. autoapi reads the source files and
  never imports the package, so no GPU and no built library are needed;
* the C reference, generated by Doxygen + Breathe from
  ``third_party/MR_AHA/include/mr_aha/mr_aha.h``, and the MATLAB reference,
  generated by ``tools/gen_matlab_api.py`` from the help blocks of
  ``third_party/MR_AHA/matlab/*.m``.

Doxygen and the MATLAB generator are run from this file, so
``sphinx-build -b html source _build/html`` is the whole build.
"""

from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO = HERE.parent
#: The library the reference pages are generated from: the pinned submodule,
#: or another checkout named by $MR_AHA_ROOT (handy while editing docstrings).
MR_AHA = Path(os.environ.get("MR_AHA_ROOT", REPO / "third_party" / "MR_AHA"))
if not (MR_AHA / "include" / "mr_aha" / "mr_aha.h").is_file():
    raise RuntimeError(
        f"MR_AHA sources not found in {MR_AHA}; run "
        "'git submodule update --init' or set MR_AHA_ROOT")

# -- Project ----------------------------------------------------------------

project = "MR_AHA"
author = "Junzhou Chen"
copyright = "2024-2026, Junzhou Chen"  # noqa: A001 - Sphinx's name

extensions = [
    "myst_parser",
    "sphinx.ext.napoleon",
    "sphinx.ext.mathjax",
    "sphinx.ext.githubpages",
    "autoapi.extension",
    "breathe",
    "sphinx_copybutton",
    "sphinx_design",
]
exclude_patterns = ["_build"]
#: Warn about every broken cross-reference.
nitpicky = False

# -- Markdown (MyST) --------------------------------------------------------

myst_enable_extensions = ["dollarmath", "amsmath", "colon_fence", "deflist"]
#: Anchors for headings down to level 3, so that pages can link to sections.
myst_heading_anchors = 3

# -- Python reference (sphinx-autoapi) --------------------------------------

autoapi_dirs = [str(MR_AHA / "python" / "mr_aha")]
autoapi_root = "api/python"
autoapi_add_toctree_entry = False
autoapi_member_order = "bysource"
autoapi_python_class_content = "both"
autoapi_options = ["members", "undoc-members", "show-inheritance",
                   "show-module-summary", "imported-members"]
#: The docstrings are Google style.
napoleon_google_docstring = True
napoleon_numpy_docstring = False
#: Render "Attributes:" as fields; autoapi already lists the attributes
#: themselves, and a second directive for each would be a duplicate.
napoleon_use_ivar = True

# -- C reference (Doxygen + Breathe) ----------------------------------------

DOXY_OUT = REPO / "doxygen"
DOXY_OUT.mkdir(exist_ok=True)
subprocess.run(
    ["doxygen", "-"], cwd=REPO, check=True,
    input=(REPO / "Doxyfile").read_text()
    + f"\nINPUT = {MR_AHA / 'include' / 'mr_aha'}\n"
    + f"OUTPUT_DIRECTORY = {DOXY_OUT}\n",
    text=True)
breathe_projects = {"mr_aha": str(DOXY_OUT / "xml")}
breathe_default_project = "mr_aha"
breathe_domain_by_extension = {"h": "c"}
#: "typedef enum mr_status {...} mr_status;" declares the enum and a typedef of
#: the same name, which the C domain reports as a duplicate declaration.
suppress_warnings = ["duplicate_declaration.c"]

# -- MATLAB reference -------------------------------------------------------

sys.path.insert(0, str(REPO / "tools"))
import gen_matlab_api  # noqa: E402

if gen_matlab_api.main(str(MR_AHA / "matlab"), str(HERE / "api" / "matlab")):
    raise RuntimeError("no MATLAB files found for the MATLAB reference")

# -- HTML -------------------------------------------------------------------

html_theme = "furo"
html_title = "MR_AHA"
html_static_path = ["_static"]
html_css_files = ["custom.css"]
html_js_files = ["sidebar-scroll.js"]
html_favicon = "_static/favicon.svg"
html_theme_options = {
    "light_logo": "wordmark-light.svg",
    "dark_logo": "wordmark-dark.svg",
    "sidebar_hide_name": True,
    # One top-of-page button, overridden in _templates/components/
    # view-this-page.html to be a GitHub icon linking to the MR_AHA repository.
    "top_of_page_buttons": ["view"],
}
templates_path = ["_templates"]
html_baseurl = "https://mikecjz.github.io/MR_AHA_docs/"
copybutton_prompt_text = r">>> |\$ "
copybutton_prompt_is_regexp = True


# -- Sidebar: "Overview" entry for the home page, above Installation -------
# A toctree "self" entry shows only on the home page itself, so the link is
# added to Furo's navigation tree on every page (after Furo has built it).


def _add_overview_link(app, pagename, templatename, context, doctree):
    tree = context.get("furo_navigation_tree")
    if not tree:
        return
    root = app.config.root_doc
    if pagename == root:
        item = (
            '<li class="toctree-l1 current current-page">'
            '<a class="current reference internal" href="#">Overview</a></li>'
        )
    else:
        href = context["pathto"](root)
        item = (
            '<li class="toctree-l1">'
            f'<a class="reference internal" href="{href}">Overview</a></li>'
        )
    start = tree.find("<ul")
    if start < 0:
        return
    end = tree.find(">", start) + 1
    context["furo_navigation_tree"] = tree[:end] + "\n" + item + tree[end:]


#: Pages that are published but not listed: they are in no toctree (``orphan``
#: front matter), carry ``<meta name="robots" content="noindex, nofollow">``,
#: and are left out of the site's search index and of ``objects.inv`` below.
#: Only a reader who has
#: the URL finds them. The Markdown source is still in this public repository.
UNLISTED_PAGES = {"benchmarks/why-bart-slower"}


def _skip_unlisted_in_search(app):
    """Keep :data:`UNLISTED_PAGES` out of ``searchindex.js``.

    Sphinx has no per-page switch for its search index, so the HTML builder's
    ``index_page`` (which feeds one page to the indexer) is wrapped to skip
    those pages.
    """
    builder = app.builder
    if not hasattr(builder, "index_page"):
        return
    index_page = builder.index_page

    def index_listed_only(pagename, doctree, title):
        if pagename not in UNLISTED_PAGES:
            index_page(pagename, doctree, title)

    builder.index_page = index_listed_only


def _hide_unlisted_from_inventory():
    """Keep :data:`UNLISTED_PAGES` out of ``objects.inv``.

    The inventory lists every document (``std:doc``) and label for
    intersphinx and similar tools; this filters the standard domain's
    objects by document name.
    """
    from sphinx.domains.std import StandardDomain  # noqa: PLC0415

    get_objects = StandardDomain.get_objects

    def listed_objects(self):
        for obj in get_objects(self):
            if obj[3] not in UNLISTED_PAGES:   # (name, dispname, type, docname, anchor, prio)
                yield obj

    StandardDomain.get_objects = listed_objects


def setup(app):
    _hide_unlisted_from_inventory()
    app.connect("html-page-context", _add_overview_link, priority=900)
    app.connect("builder-inited", _skip_unlisted_in_search)
